<script setup lang="ts">
import {computed,nextTick,ref,watch} from 'vue';
import {Button} from './button';
export interface NavigationTreeItem {id:string;label:string;depth:number;expandable:boolean;expanded:boolean;current:boolean;hasDocument:boolean;title?:string}
const props=defineProps<{items:NavigationTreeItem[];label:string;searching?:boolean}>();
const emit=defineEmits<{toggle:[id:string];select:[id:string]}>();
const box=ref<HTMLElement>(),scroll=ref(0),focusId=ref('');const rowHeight=38;
const start=computed(()=>Math.max(0,Math.floor(scroll.value/rowHeight)-5)),slice=computed(()=>props.items.slice(start.value,start.value+28));
const tabId=computed(()=>slice.value.some(item=>item.id===focusId.value)?focusId.value:(slice.value[Math.min(5,slice.value.length-1)]?.id??''));
const siblingMetadata=computed(()=>{const parents:string[]=[],counts=new Map<string,number>(),rows:{key:string;position:number}[]=[];for(const item of props.items){parents.length=item.depth;const key=JSON.stringify([item.depth,parents[item.depth-1]??'']),position=(counts.get(key)??0)+1;counts.set(key,position);rows.push({key,position});parents[item.depth]=item.id;}return rows.map(row=>({position:row.position,size:counts.get(row.key)!}));});
watch(()=>props.items,items=>{if(!items.some(item=>item.id===focusId.value))focusId.value=items.find(item=>item.current)?.id??items[0]?.id??'';},{immediate:true});
function reset(){if(box.value)box.value.scrollTop=0;scroll.value=0;}
function reveal(id:string){const i=props.items.findIndex(item=>item.id===id);if(i<0||!box.value)return;box.value.scrollTop=i*rowHeight;scroll.value=box.value.scrollTop;}
async function focus(i:number){const item=props.items[Math.max(0,Math.min(i,props.items.length-1))];if(!item||!box.value)return;focusId.value=item.id;const top=props.items.indexOf(item)*rowHeight,bottom=top+rowHeight;if(top<box.value.scrollTop)box.value.scrollTop=top;else if(bottom>box.value.scrollTop+box.value.clientHeight)box.value.scrollTop=bottom-box.value.clientHeight;scroll.value=box.value.scrollTop;await nextTick();box.value?.querySelector<HTMLElement>(`[data-row-index="${props.items.indexOf(item)}"]`)?.focus();}
function activate(item:NavigationTreeItem){if(item.hasDocument)emit('select',item.id);else if(item.expandable&&!props.searching)emit('toggle',item.id);}
function key(event:KeyboardEvent,index:number){const item=props.items[index];if(!item)return;let destination:number|undefined;
 switch(event.key){case 'ArrowDown':destination=index+1;break;case 'ArrowUp':destination=index-1;break;case 'Home':destination=0;break;case 'End':destination=props.items.length-1;break;case 'ArrowRight':if(item.expandable&&!item.expanded&&!props.searching)emit('toggle',item.id);else if(props.items[index+1]?.depth>item.depth)destination=index+1;break;case 'ArrowLeft':if(item.expandable&&item.expanded&&!props.searching)emit('toggle',item.id);else for(let i=index-1;i>=0;i--)if(props.items[i]!.depth<item.depth){destination=i;break;}break;case 'Enter':case ' ':if((event.target as HTMLElement).getAttribute('role')!=='treeitem')return;activate(item);break;default:return;}
 event.preventDefault();if(destination!==undefined)void focus(destination);
}
defineExpose({reveal,reset});
</script>
<template><div ref="box" class="ocp-navigation-scroll" @scroll="scroll=($event.target as HTMLElement).scrollTop"><div role="tree" :aria-label="label" :style="{height:items.length*rowHeight+'px',position:'relative'}"><div v-for="(item,i) in slice" :key="item.id" role="treeitem" :data-row-index="start+i" :aria-level="item.depth+1" :aria-posinset="siblingMetadata[start+i]?.position" :aria-setsize="siblingMetadata[start+i]?.size" :aria-expanded="item.expandable?item.expanded:undefined" :aria-selected="item.current" :tabindex="item.id===tabId?0:-1" class="ocp-navigation-row" :class="{'is-current':item.current}" :style="{top:(start+i)*rowHeight+'px',paddingLeft:(item.depth*14)+'px'}" @focusin="focusId=item.id" @keydown="key($event,start+i)"><Button v-if="item.expandable" variant="ghost" size="icon" class="ocp-navigation-toggle" tabindex="-1" :disabled="searching" :aria-label="(item.expanded?'收起':'展开')+' '+item.label" :aria-expanded="item.expanded" @click="emit('toggle',item.id)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true" :class="{expanded:item.expanded}"><path d="m9 5 7 7-7 7"/></svg></Button><span v-else class="ocp-navigation-toggle"/><Button variant="ghost" size="sm" class="ocp-navigation-label" tabindex="-1" :aria-current="item.current?'page':undefined" :title="item.title" @click="activate(item)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path :d="item.expandable?'M3 7h7l2 2h9v11H3Z M3 7V4h7l2 3':'M6 3h8l4 4v14H6Z M14 3v5h4 M9 12h6 M9 16h6'"/></svg><span>{{item.label}}</span></Button></div></div></div></template>
<style scoped>.ocp-navigation-scroll{height:560px;overflow:auto;margin-top:8px}.ocp-navigation-row{position:absolute;height:38px;width:100%;display:flex;align-items:center;border-radius:6px;box-sizing:border-box;outline:none}.ocp-navigation-row:focus-visible{box-shadow:inset 0 0 0 2px var(--ocp-ring)}.ocp-navigation-row.is-current{background:var(--ocp-muted-background);color:var(--ocp-primary)}.ocp-navigation-row .ocp-navigation-label,.ocp-navigation-row .ocp-navigation-toggle{color:var(--ocp-foreground)}.ocp-navigation-toggle{width:28px;height:32px;flex:none;padding:6px}.ocp-navigation-toggle svg{width:14px;height:14px;transition:transform .15s}.ocp-navigation-toggle svg.expanded{transform:rotate(90deg)}.ocp-navigation-label{min-width:0;flex:1;height:34px;justify-content:flex-start;padding:6px;gap:8px;font-weight:400}.ocp-navigation-label svg{width:16px;height:16px;flex:none;opacity:.7}.ocp-navigation-label span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.ocp-navigation-label[aria-current=page]{font-weight:600}@media(prefers-reduced-motion:reduce){.ocp-navigation-toggle svg{transition:none}}</style>
